const COLS = 24;
const ROWS = 18;
const START_MS = 200;
const VECTORS = { up: { x: 0, y: -1 }, down: { x: 0, y: 1 }, left: { x: -1, y: 0 }, right: { x: 1, y: 0 } };
const OPPOSITE = { up: 'down', down: 'up', left: 'right', right: 'left' };

function clone(value) { return JSON.parse(JSON.stringify(value)); }
function wrap(value, size) { return (value + size) % size; }
function same(a, b) { return a.x === b.x && a.y === b.y; }

// The only source of randomness. The seed lives in the state, so a replay is identical.
function nextRandom(state) {
  state.seed = (Math.imul(state.seed, 1664525) + 1013904223) >>> 0;
  return state.seed / 4294967296;
}

function occupied(state, cell) {
  return [...state.snake, ...state.stars, ...state.comets, ...state.extras].some(item => same(item, cell));
}

// A random cell that holds nothing and is at least `distance` steps from the head.
function freeCell(state, distance = 0) {
  const head = state.snake[0];
  for (let tries = 0; tries < 500; tries++) {
    const cell = { x: Math.floor(nextRandom(state) * COLS), y: Math.floor(nextRandom(state) * ROWS) };
    if (!occupied(state, cell) && Math.abs(cell.x - head.x) + Math.abs(cell.y - head.y) >= distance) return cell;
  }
  return null;
}

function spawnStar(state) {
  const cell = freeCell(state);
  if (cell) state.stars.push(cell);
}

function spawnComet(state) {
  const cell = freeCell(state, 8);
  if (!cell) return;
  const direction = Object.values(VECTORS)[Math.floor(nextRandom(state) * 4)];
  state.comets.push({ x: cell.x, y: cell.y, dx: direction.x, dy: direction.y });
}

function spawnExtra(state, kind) {
  const cell = freeCell(state);
  if (cell) state.extras.push({ x: cell.x, y: cell.y, kind });
}

function init(seed) {
  const state = {
    snake: [{ x: 6, y: 9 }, { x: 5, y: 9 }, { x: 4, y: 9 }],
    dir: 'right',
    stars: [],
    comets: [],
    extras: [],
    score: 0,
    eaten: 0,
    tickMs: START_MS,
    ticks: 0,
    over: false,
    reason: null,
    shield: false,
    seed: (seed >>> 0) + 1,
  };
  spawnStar(state);
  spawnComet(state);
  spawnComet(state);
  return state;
}

// One tick of the game. Returns a new state and leaves `previous` untouched.
function step(previous, input) {
  if (previous.over) return previous;

  const state = clone(previous);

  if (input && VECTORS[input] && input !== OPPOSITE[state.dir]) {
    state.dir = input;
  }

  const vector = VECTORS[state.dir];
  const oldHead = state.snake[0];
  const head = {
    x: wrap(oldHead.x + vector.x, COLS),
    y: wrap(oldHead.y + vector.y, ROWS),
  };

  const oldComets = state.comets.map(comet => ({ x: comet.x, y: comet.y }));
  for (const comet of state.comets) {
    comet.x = wrap(comet.x + comet.dx, COLS);
    comet.y = wrap(comet.y + comet.dy, ROWS);
  }

  state.snake.unshift(head);

  const starIndex = state.stars.findIndex(item => same(item, head));
  const ateStar = starIndex >= 0;
  if (ateStar) {
    state.stars.splice(starIndex, 1);
    state.score += 1;
    state.eaten += 1;

    if (state.eaten % 5 === 0) {
      state.tickMs = Math.max(60, state.tickMs - 20);
      if (state.comets.length < 6) spawnComet(state);
    }
    if (state.eaten % 4 === 0) spawnExtra(state, 'shield');

    spawnStar(state);
  } else {
    state.snake.pop();
  }

  const shieldIndex = state.extras.findIndex(extra => extra.kind === 'shield' && same(extra, head));
  if (shieldIndex >= 0) {
    state.extras.splice(shieldIndex, 1);
    state.shield = true;
  }

  const cometHitIndices = [];
  for (let i = 0; i < state.comets.length; i++) {
    const comet = state.comets[i];
    const swapped = same(oldHead, comet) && same(head, oldComets[i]);
    if (same(head, comet) || swapped) cometHitIndices.push(i);
  }

  for (let i = cometHitIndices.length - 1; i >= 0; i--) {
    const index = cometHitIndices[i];
    if (state.shield) {
      state.shield = false;
      state.comets.splice(index, 1);
    } else {
      state.over = true;
      state.reason = 'comet';
      break;
    }
  }

  if (!state.over) {
    // The tail has already been removed when the snake did not grow, so
    // every remaining segment after the head is a body cell to check.
    if (state.snake.slice(1).some(segment => same(segment, head))) {
      state.over = true;
      state.reason = 'self';
    }
  }

  state.ticks += 1;
  return state;
}

